                || (!self.stop_signs.is_empty() && !policy.preserve_stop_signs)
                || (!self.yield_intersections.is_empty() && !policy.preserve_yield_intersections)
                || self.lidar3d.is_some()
                || self.multi_height_lidar.is_some()
