        let mut planner = LatticePlanner {
            max_lateral_acceleration_m_s2: Some(0.6),
            ..LatticePlanner::default()
        };
        let path = planner.plan(
            EgoState {
                speed: 0.0,
                ..EgoState::default()
            },
            &road(5.5),
            &[obstacle()],
